function houseOfCards(n) {
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  for (let triangles = 1; 3 * triangles - 1 <= n; triangles++) {
    const cost = 3 * triangles - 1;
    for (let cards = n; cards >= cost; cards--) {
      dp[cards] += dp[cards - cost];
    }
  }
  return dp[n];
}

