function houseOfCards(n) {
  // Build from the bottom row up; each new row has fewer triangles than the one under it.
  const memo = new Map();
  const finish = (left, limit) => {
    if (left === 0) return 1;
    const key = left + ',' + limit;
    if (memo.has(key)) return memo.get(key);
    let ways = 0;
    for (let t = 1; t <= limit; t++) {
      const used = 2 * t + (t - 1);
      if (used > left) break;
      ways += finish(left - used, t - 1);
    }
    memo.set(key, ways);
    return ways;
  };
  return finish(n, n);
}

